<script setup lang="ts">
import { ArrowRight, Location, MoreFilled, Plus, MagicStick } from '@element-plus/icons-vue'
import type { ItineraryItem } from '@/types/itinerary'
import { distanceKm, placeTypeLabels } from '@/utils/workspace'
import PlaceThumbnail from './PlaceThumbnail.vue'
defineProps<{ items: ItineraryItem[]; day: string; selectedId: number | null; hasPlaces: boolean }>()
const emit = defineEmits<{ select: [item: ItineraryItem]; edit: [item: ItineraryItem]; remove: [item: ItineraryItem]; add: []; schedule: []; discover: [] }>()
function duration(item: ItineraryItem) { const [sh, sm] = item.start_time.split(':').map(Number), [eh, em] = item.end_time.split(':').map(Number); const minutes = eh * 60 + em - sh * 60 - sm; return minutes > 0 ? `${minutes >= 60 ? `${Math.floor(minutes / 60)} 小时` : ''}${minutes % 60 ? ` ${minutes % 60} 分钟` : ''}` : '' }
function distance(items: ItineraryItem[], i: number) { if (!i) return null; const value = distanceKm(items[i - 1].place, items[i].place); return value === null ? null : `${value.toFixed(1)} km` }
</script>
<template>
  <section id="daily-timeline" class="daily-timeline" role="tabpanel" :aria-labelledby="`day-${day}`">
    <div v-if="!items.length" class="timeline-empty"><el-icon><MagicStick /></el-icon><h3>给这一天，留些好安排</h3><p>{{ hasPlaces ? '从收藏地点自动排程，或亲手添加第一站。' : '让 AI 推荐一些好去处，收藏后就能排进行程。' }}</p><el-button type="primary" @click="hasPlaces ? emit('schedule') : emit('discover')">{{ hasPlaces ? '从收藏地点排程' : '让 AI 帮我规划' }}<el-icon class="button-trailing"><ArrowRight /></el-icon></el-button></div>
    <ol v-else class="itinerary-list"><li v-for="(item, i) in items" :key="item.id" class="itinerary-row" :class="{ 'is-selected': selectedId === item.id }"><time :datetime="`${day}T${item.start_time}`">{{ item.start_time.slice(0,5) }}</time><span class="timeline-track"><span class="timeline-dot" /></span><button class="itinerary-stop" :aria-label="`在地图查看${item.place.name}`" @click="emit('select', item)"><PlaceThumbnail :src="item.place.image_url" :type="item.place.type" :name="item.place.name" /><span class="stop-copy"><strong>{{ item.place.name }}</strong><span class="stop-description">{{ item.note || item.place.note || `${placeTypeLabels[item.place.type] ?? '地点'} · ${duration(item)}` }}</span><small><el-icon><Location /></el-icon><template v-if="distance(items, i)">距上一站 {{ distance(items, i) }} · 直线</template><template v-else>{{ item.place.address || '地址待补充' }}</template></small></span></button><el-dropdown trigger="click" @command="(command: string) => command === 'edit' ? emit('edit', item) : emit('remove', item)"><button class="icon-button item-menu" :aria-label="`${item.place.name}的更多操作`"><el-icon><MoreFilled /></el-icon></button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">修改日期 / 时间</el-dropdown-item><el-dropdown-item command="remove">删除行程项</el-dropdown-item></el-dropdown-menu></template></el-dropdown></li></ol>

  </section>
</template>
<style scoped>
