ff}.timeline-empty{min-height:330px;display:flex;align-items:center;justify-content:center;flex-direction:column;text-align:center;padding:24px}.timeline-empty>.el-icon{font-size:30px;color:#818bfb;margin-bottom:16px}.timeline-empty h3{font-size:16px;margin:0 0 10px}.timeline-empty p{font-size:12px;color:var(--secondary);max-width:250px;line-height:1.7;margin:0 0 20px}.button-trailing{margin-left:8px}
