@media(min-width:760px) and (max-width:1499px){.itinerary-row{min-height:62px}.itinerary-row>time{padding-top:21px}.timeline-track:before{top:25px;bottom:-25px}.timeline-dot{top:23px}.itinerary-stop{padding:4px 0}.itinerary-stop :deep(.place-thumbnail){width:52px;height:50px}.stop-copy{gap:2px}.stop-copy strong{line-height:1.2}.stop-description{line-height:1.3}.stop-copy small{font-size:10px}}
@media(max-width:759px){.itinerary-row{grid-template-columns:38px 16px minmax(0,1fr) 22px}.place-thumbnail{width:56px;height:53px}.itinerary-stop{gap:10px}.stop-copy strong{font-size:13px}}
